<attribute NAME="execute_scripts_without_write_restriction" VALUE="true"/>
<attribute NAME="execute_scripts_without_exec_restriction" VALUE="true"/>
<attribute NAME="execute_scripts_without_network_restriction" VALUE="true"/>
<node TEXT="// --- Imports ---&#xa;// Core LLM Addon Classes&#xa;import com.barrymac.freeplane.addons.llm.ConfigManager&#xa;import com.barrymac.freeplane.addons.llm.ResponseProcessor&#xa;import com.barrymac.freeplane.addons.llm.ApiConfig // Needed for type hint&#xa;&#xa;// API related classes&#xa;import com.barrymac.freeplane.addons.llm.api.ApiCallerFactory&#xa;import com.barrymac.freeplane.addons.llm.api.ModelCompatibility&#xa;&#xa;// Map related classes&#xa;import com.barrymac.freeplane.addons.llm.maps.NodeTagger&#xa;import com.barrymac.freeplane.addons.llm.maps.NodeHelper&#xa;import com.barrymac.freeplane.addons.llm.maps.MapUpdater&#xa;&#xa;// Prompt related classes&#xa;import com.barrymac.freeplane.addons.llm.prompts.MessageLoader&#xa;import com.barrymac.freeplane.addons.llm.prompts.DimensionGenerator&#xa;import com.barrymac.freeplane.addons.llm.prompts.PromptBuilder&#xa;import com.barrymac.freeplane.addons.llm.ui.CompareDialogueHelper&#xa;&#xa;// UI related classes&#xa;import com.barrymac.freeplane.addons.llm.ui.DialogHelper&#xa;import com.barrymac.freeplane.addons.llm.ui.UiHelper&#xa;&#xa;// Freeplane specific classes&#xa;&#xa;// Ensure LogUtils is imported&#xa;&#xa;// Standard Java/Swing classes&#xa;&#xa;// Explicitly needed by UiHelper methods used here&#xa;&#xa;// Ensure LogUtils is imported&#xa;import org.freeplane.core.util.LogUtils&#xa;&#xa;import static com.barrymac.freeplane.addons.llm.ui.CompareDialogueHelper.*&#xa;&#xa;// --- Initialize Core Components ---&#xa;// Load configuration FIRST&#xa;ApiConfig apiConfig = ConfigManager.loadBaseConfig(config)&#xa;&#xa;// Create instances of required classes using the loaded config&#xa;// Pass only &apos;ui&apos; to createApiCaller, as logger is no longer needed by the factory&#xa;def apiCallerClosures = ApiCallerFactory.createApiCaller([ui: ui])&#xa;if (!apiCallerClosures) {&#xa;    throw new Exception(&quot;Failed to create API caller closures.&quot;)&#xa;}&#xa;NodeTagger nodeTagger = new NodeTagger()&#xa;&#xa;// Get method references for commonly used functions&#xa;// Get the specific make_api_call closure from the returned map&#xa;Closure make_api_call = apiCallerClosures.make_api_call&#xa;Closure addModelTagRecursively = nodeTagger.&amp;tagWithModel&#xa;&#xa;// Load messages&#xa;def messages = MessageLoader.loadComparisonMessages(config)&#xa;def systemMessageTemplate = messages.systemTemplate&#xa;def compareNodesUserMessageTemplate = messages.userTemplate&#xa;&#xa;// --- Main Script Logic ---&#xa;&#xa;// Wrap the entire script in a try-catch block for better error handling&#xa;try {&#xa;&#xa;    // Check if templates are loaded&#xa;    if (systemMessageTemplate.isEmpty() || compareNodesUserMessageTemplate.isEmpty()) {&#xa;        throw new Exception(&quot;System message template or the dedicated compareNodesUserMessage.txt is missing or empty. Please check configuration or files.&quot;)&#xa;    }&#xa;&#xa;    // 2. Get Selected Nodes and Validate (Use NodeHelper class from deps)&#xa;    def selectedNodes = c.selecteds&#xa;    // Use the static method directly via the class obtained from deps&#xa;    def nodes = NodeHelper.validateSelectedNodes(selectedNodes) // This might throw ValidationException&#xa;    def sourceNode = nodes[0]&#xa;    def targetNode = nodes[1]&#xa;&#xa;    LogUtils.info(&quot;Selected nodes for comparison: ${sourceNode.text} and ${targetNode.text}&quot;)&#xa;&#xa;    // 3. Get Comparison Type from User&#xa;    def dialogMessage = &quot;Comparing selected nodes:\n&apos;${sourceNode.text}&apos;\nand\n&apos;${targetNode.text}&apos;\nEnter comparison type:&quot;&#xa;    def defaultComparisonTypes = [&quot;Pros and Cons&quot;, &quot;Compare and Contrast&quot;, &quot;Strengths vs Weaknesses&quot;, &quot;Advantages and Disadvantages&quot;]&#xa;    def comparisonTypesConfigKey = &quot;promptLlmAddOn.comparisonTypes&quot;&#xa;&#xa;    String comparisonType = showComparisonDialog(&#xa;        ui, &#xa;        config, &#xa;        sourceNode.delegate, &#xa;        dialogMessage,&#xa;        defaultComparisonTypes,&#xa;        comparisonTypesConfigKey&#xa;    )&#xa;&#xa;    if (comparisonType == null || comparisonType.trim().isEmpty()) {&#xa;        LogUtils.info(&quot;User cancelled comparison input.&quot;)&#xa;        return&#xa;    }&#xa;    comparisonType = comparisonType.trim()&#xa;&#xa;    // 4. Show Progress Dialog&#xa;    def progressMessage = &quot;Generating &apos;${comparisonType}&apos; analysis framework...&quot;&#xa;    def dialog = DialogHelper.createProgressDialog(ui, &quot;Analyzing Nodes with LLM...&quot;, progressMessage)&#xa;    dialog.setVisible(true)&#xa;&#xa;    // 6. Run API Calls in Background Thread&#xa;    def workerThread = new Thread({&#xa;        String errorMessage = null&#xa;&#xa;        try {&#xa;            // --- Generate Comparative Dimension with Validation ---&#xa;            def dimensionData = DimensionGenerator.generateDimension(&#xa;                make_api_call.curry(apiConfig.provider, apiConfig.apiKey),&#xa;                apiConfig.provider,&#xa;                apiConfig.model,&#xa;                messages.dimensionSystemTemplate, &#xa;                comparisonType&#xa;            )&#xa;            def (pole1, pole2) = [dimensionData.pole1, dimensionData.pole2]&#xa;            def comparativeDimension = &quot;${pole1} vs ${pole2}&quot;&#xa;            LogUtils.info(&quot;Generated comparative dimension: ${comparativeDimension}&quot;)&#xa;            &#xa;            // --- Prepare Prompts with Generated Dimension ---&#xa;            LogUtils.info(&quot;CompareNodes: Final userMessageTemplate for expansion:\n---\n${compareNodesUserMessageTemplate}\n---&quot;)&#xa;            &#xa;            def sourceUserPrompt = PromptBuilder.buildComparisonPrompt(&#xa;                sourceNode, targetNode, &#xa;                compareNodesUserMessageTemplate,&#xa;                comparativeDimension, pole1, pole2&#xa;            )&#xa;            LogUtils.info(&quot;CompareNodes: Source User Prompt:\n${sourceUserPrompt}&quot;)&#xa;            &#xa;            def targetUserPrompt = PromptBuilder.buildComparisonPrompt(&#xa;                targetNode, sourceNode,&#xa;                compareNodesUserMessageTemplate,&#xa;                comparativeDimension, pole1, pole2 &#xa;            )&#xa;            LogUtils.info(&quot;CompareNodes: Target User Prompt:\n${targetUserPrompt}&quot;)&#xa;            &#xa;            // Update progress dialog&#xa;            UiHelper.updateDialogMessage(dialog, &quot;Analyzing &apos;${sourceNode.text}&apos; and &apos;${targetNode.text}&apos; using &apos;${comparativeDimension}&apos; framework...&quot;)&#xa;&#xa;            // --- Prepare System Prompts ---&#xa;            LogUtils.info(&quot;CompareNodes: Final systemMessageTemplate for expansion:\n---\n${systemMessageTemplate}\n---&quot;)&#xa;&#xa;            def sourceSystemPrompt = PromptBuilder.buildSystemPrompt(&#xa;                sourceNode, targetNode,&#xa;                systemMessageTemplate,&#xa;                comparativeDimension, pole1, pole2&#xa;            )&#xa;            LogUtils.info(&quot;CompareNodes: Source System Prompt:\n${sourceSystemPrompt}&quot;)&#xa;&#xa;            def targetSystemPrompt = PromptBuilder.buildSystemPrompt(&#xa;                targetNode, sourceNode,&#xa;                systemMessageTemplate,&#xa;                comparativeDimension, pole1, pole2&#xa;            )&#xa;            LogUtils.info(&quot;CompareNodes: Target System Prompt:\n${targetSystemPrompt}&quot;)&#xa;&#xa;            // --- Define Helper Closure for API Call with Retry ---&#xa;            def callApiAndParseWithRetry = { String nodeName, Map initialPayload -&gt;&#xa;                Map analysisResult = [error: &quot;Initial error state&quot;] // Default error state&#xa;                String lastRawApiResponse = &quot;&quot; // Store last raw response for retry message&#xa;                final int MAX_RETRIES = 2 // Allow up to 2 retries (3 attempts total)&#xa;&#xa;                for (int attempt = 1; attempt &lt;= MAX_RETRIES + 1; attempt++) {&#xa;                    LogUtils.info(&quot;Attempt ${attempt}/${MAX_RETRIES + 1} for node &apos;${nodeName}&apos;&quot;)&#xa;                    def currentPayload = initialPayload // Use initial payload for first attempt&#xa;&#xa;                    // --- Prepare Payload for Retry Attempts ---&#xa;                    if (attempt &gt; 1) {&#xa;                        // Update dialog for retry&#xa;                        UiHelper.updateDialogMessageThreadSafe(dialog, &quot;Attempt ${attempt}: LLM response format incorrect for &apos;${nodeName}&apos;. Retrying...&quot;)&#xa;&#xa;                        // Construct retry message specifically asking for ONLY JSON&#xa;                        def retryUserMessage = &quot;&quot;&quot;&#xa;                        Your previous response was not valid JSON or contained extra text.&#xa;                        Please strictly adhere to the requested JSON format.&#xa;                        DO NOT include any text before or after the JSON structure (like &apos;Here is the JSON...&apos; or explanations).&#xa;                        Provide ONLY the JSON object starting with &apos;{&apos; and ending with &apos;}&apos;.&#xa;&#xa;                        Previous invalid response snippet (first 200 chars):&#xa;                        ${lastRawApiResponse.take(200)}...&#xa;&#xa;                        Please try again, providing only the valid JSON for the original request:&#xa;                        &apos;$comparativeDimension&apos; ($pole1 vs $pole2) for &apos;$nodeContent&apos; and &apos;$otherNodeContent&apos;.&#xa;                        &quot;&quot;&quot;.stripIndent().trim() // Use trim()&#xa;&#xa;                        // Modify the payload for retry: Add previous assistant response and new user instruction&#xa;                        def retryMessages = new ArrayList&lt;&gt;(initialPayload.messages)&#xa;                        // Add the *entire* previous raw response as the assistant&apos;s turn&#xa;                        retryMessages.add([role: &apos;assistant&apos;, content: lastRawApiResponse])&#xa;                        retryMessages.add([role: &apos;user&apos;, content: retryUserMessage])&#xa;&#xa;                        // Create a new payload map for the retry call&#xa;                        currentPayload = new HashMap&lt;&gt;(initialPayload) // Create a copy&#xa;                        currentPayload.messages = retryMessages&#xa;                        // Ensure response_format is still set if applicable&#xa;                        currentPayload[&apos;response_format&apos;] = initialPayload[&apos;response_format&apos;]&#xa;                        currentPayload = currentPayload.findAll { key, value -&gt; value != null } // Clean nulls again&#xa;&#xa;                        LogUtils.info(&quot;Retry attempt ${attempt} for &apos;${nodeName}&apos;. Sending correction request.&quot;)&#xa;                    }&#xa;&#xa;                    // --- Make API Call ---&#xa;                    def apiResponse = make_api_call(apiConfig.provider, apiConfig.apiKey, currentPayload)&#xa;                    if (apiResponse == null || apiResponse.isEmpty()) {&#xa;                        analysisResult = [error: &quot;Received empty or null response (Attempt ${attempt})&quot;]&#xa;                        lastRawApiResponse = &quot;&quot; // Reset raw response&#xa;                        if (attempt &gt; MAX_RETRIES) break // Exit loop if max retries reached&#xa;                        Thread.sleep(500) // Small delay before retry&#xa;                        continue // Go to next retry attempt&#xa;                    }&#xa;                    lastRawApiResponse = apiResponse // Store for potential next retry&#xa;&#xa;                    // --- Process Response ---&#xa;                    try {&#xa;                        // Try parsing the response - ResponseProcessor calls ResponseParser internally&#xa;                        analysisResult = ResponseProcessor.parseApiResponse(apiResponse, pole1, pole2)&#xa;                        // Check if the *parsed* result contains an error key (set by ResponseParser on failure)&#xa;                        if (!analysisResult.error) {&#xa;                            LogUtils.info(&quot;Successfully parsed response for &apos;${nodeName}&apos; on attempt ${attempt}&quot;)&#xa;                            return analysisResult // Success! Exit the retry loop and return result.&#xa;                        } else {&#xa;                            // Parsing failed, error message is in analysisResult.error&#xa;                            LogUtils.warn(&quot;Parsing failed on attempt ${attempt} for &apos;${nodeName}&apos;: ${analysisResult.error}&quot;)&#xa;                            // Loop will continue if retries remain&#xa;                        }&#xa;                    } catch (Exception parseEx) {&#xa;                        // Catch unexpected errors during parsing itself&#xa;                        LogUtils.warn(&quot;Unexpected processing/parsing exception on attempt ${attempt} for &apos;${nodeName}&apos;: ${parseEx.message}&quot;)&#xa;                        analysisResult = [error: &quot;Unexpected processing error: ${parseEx.message} (Attempt ${attempt})&quot;]&#xa;                        // Loop will continue if retries remain&#xa;                    }&#xa;&#xa;                    // If we reach here and it&apos;s the last attempt, the loop will terminate&#xa;                    if (attempt &gt; MAX_RETRIES) {&#xa;                         LogUtils.warn(&quot;Max retries reached for &apos;${nodeName}&apos;. Final error: ${analysisResult.error ?: &apos;Unknown parsing failure&apos;}&quot;)&#xa;                    }&#xa;                    Thread.sleep(500) // Small delay before retry&#xa;                }&#xa;                // If loop finishes without success, return the last error state&#xa;                return analysisResult&#xa;            }&#xa;&#xa;            // --- Prepare Initial Payloads ---&#xa;            def compatParams = ModelCompatibility.chatParams(apiConfig.provider, apiConfig.model,&#xa;                apiConfig.temperature, apiConfig.maxTokens)&#xa;&#xa;            Map&lt;String, Object&gt; sourcePayloadMap = [&#xa;                &apos;model&apos;: apiConfig.model,&#xa;                &apos;messages&apos;: [&#xa;                    [role: &apos;system&apos;, content: sourceSystemPrompt],&#xa;                    [role: &apos;user&apos;, content: sourceUserPrompt]&#xa;                ],&#xa;                &apos;response_format&apos;: responseFormat&#xa;            ] + compatParams&#xa;&#xa;            Map&lt;String, Object&gt; targetPayloadMap = [&#xa;                &apos;model&apos;: apiConfig.model,&#xa;                &apos;messages&apos;: [&#xa;                    [role: &apos;system&apos;, content: targetSystemPrompt],&#xa;                    [role: &apos;user&apos;, content: targetUserPrompt]&#xa;                ],&#xa;                &apos;response_format&apos;: responseFormat&#xa;            ] + compatParams&#xa;&#xa;            sourcePayloadMap = sourcePayloadMap.findAll { key, value -&gt; value != null }&#xa;            targetPayloadMap = targetPayloadMap.findAll { key, value -&gt; value != null }&#xa;&#xa;            // --- Call APIs using the Retry Helper ---&#xa;            UiHelper.updateDialogMessageThreadSafe(dialog, &quot;Requesting analysis for &apos;${sourceNode.text}&apos;...&quot;)&#xa;            def sourceAnalysis = callApiAndParseWithRetry(sourceNode.text, sourcePayloadMap)&#xa;            if (sourceAnalysis.error) {&#xa;                throw new Exception(&quot;Failed to get valid analysis for &apos;${sourceNode.text}&apos; after multiple attempts: ${sourceAnalysis.error}&quot;)&#xa;            }&#xa;            LogUtils.info(&quot;Source Node Analysis received and parsed successfully.&quot;)&#xa;&#xa;            UiHelper.updateDialogMessageThreadSafe(dialog, &quot;Requesting analysis for &apos;${targetNode.text}&apos;...&quot;)&#xa;            def targetAnalysis = callApiAndParseWithRetry(targetNode.text, targetPayloadMap)&#xa;            if (targetAnalysis.error) {&#xa;                throw new Exception(&quot;Failed to get valid analysis for &apos;${targetNode.text}&apos; after multiple attempts: ${targetAnalysis.error}&quot;)&#xa;            }&#xa;            LogUtils.info(&quot;Target Node Analysis received and parsed successfully.&quot;)&#xa;&#xa;            // Add validation for pole consistency (using the poles from the parsed results)&#xa;            // Check if dimension exists before accessing poles&#xa;            if (!sourceAnalysis?.dimension?.pole1 || !sourceAnalysis?.dimension?.pole2 ||&#xa;                !targetAnalysis?.dimension?.pole1 || !targetAnalysis?.dimension?.pole2 ||&#xa;                sourceAnalysis.dimension.pole1 != targetAnalysis.dimension.pole1 ||&#xa;                sourceAnalysis.dimension.pole2 != targetAnalysis.dimension.pole2) {&#xa;                 // Log the actual dimensions found for debugging&#xa;                 LogUtils.warn(&quot;Source dimension: ${sourceAnalysis?.dimension}&quot;)&#xa;                 LogUtils.warn(&quot;Target dimension: ${targetAnalysis?.dimension}&quot;)&#xa;                 throw new Exception(&quot;Mismatched or missing comparison dimensions between concepts. Check LLM response format.&quot;)&#xa;            }&#xa;&#xa;            // --- Update Map on EDT ---&#xa;            UiHelper.disposeDialog(dialog) // Close progress dialog first&#xa;            if (sourceAnalysis.isEmpty() &amp;&amp; targetAnalysis.isEmpty()) {&#xa;                UiHelper.showInformationMessage(ui, &quot;The LLM analysis did not yield structured results for either node.&quot;)&#xa;            } else {&#xa;                try {&#xa;                    MapUpdater.createComparisonStructure(&#xa;                        sourceNode,&#xa;                        targetNode,&#xa;                        sourceAnalysis,&#xa;                        targetAnalysis,&#xa;                        comparativeDimension,&#xa;                        pole1,&#xa;                        pole2,&#xa;                        apiConfig.model,&#xa;                        addModelTagRecursively&#xa;                    )&#xa;&#xa;                    UiHelper.showInformationMessage(ui, &quot;Central comparison node using &apos;${comparativeDimension}&apos; created.&quot;)&#xa;&#xa;                } catch (Exception e) {&#xa;                    LogUtils.warn(&quot;Error creating central comparison node structure on EDT: ${e.message}&quot;, e)&#xa;                    UiHelper.showErrorMessage(ui, &quot;Failed to add central comparison node to the map. Check logs. Error: ${e.message}&quot;)&#xa;                }&#xa;            }&#xa;&#xa;        } catch (Exception e) {&#xa;            LogUtils.warn(&quot;LLM Comparison failed: ${e.message}&quot;, e)&#xa;            errorMessage = &quot;Comparison Error: ${e.message.split(&apos;\n&apos;).head()}&quot;&#xa;            // Ensure dialog is closed and error shown on EDT&#xa;            UiHelper.disposeDialog(dialog)&#xa;            UiHelper.showErrorMessage(ui, errorMessage)&#xa;        }&#xa;    })&#xa;    workerThread.start()&#xa;&#xa;} catch (Exception e) {&#xa;    // Handle all errors with a simple message&#xa;    UiHelper.showErrorMessage(ui, e.message)&#xa;    LogUtils.warn(&quot;Error in CompareConnectedNodes: ${e.message}&quot;, e)&#xa;}&#xa;&#xa;LogUtils.info(&quot;CompareConnectedNodes script finished.&quot;)&#xa;&#xa;" ID="ID_1983021896" CREATED="1794972873863" MODIFIED="1794972873864"/>
</node>
<node TEXT="GenerateImage.groovy" FOLDED="true" ID="ID_GENERATE_IMAGE" CREATED="1744150000000" MODIFIED="1744150000000">
<attribute_layout NAME_WIDTH="202.49999 pt" VALUE_WIDTH="156.75 pt"/>
<attribute NAME="menuTitleKey" VALUE="addons.${name}.generateImage"/>
<attribute NAME="menuLocation" VALUE="${addonsMenu}"/>
<attribute NAME="executionMode" VALUE="on_single_node"/>
<attribute NAME="keyboardShortcut" VALUE=""/>
<attribute NAME="execute_scripts_without_asking" VALUE="true"/>
<attribute NAME="execute_scripts_without_file_restriction" VALUE="true"/>
<attribute NAME="execute_scripts_without_write_restriction" VALUE="true"/>
<attribute NAME="execute_scripts_without_exec_restriction" VALUE="true"/>
<attribute NAME="execute_scripts_without_network_restriction" VALUE="true"/>
<node TEXT="import com.barrymac.freeplane.addons.llm.api.ApiRequest&#xa;import com.barrymac.freeplane.addons.llm.prompts.Message&#xa;import com.barrymac.freeplane.addons.llm.ConfigManager&#xa;import com.barrymac.freeplane.addons.llm.ConfigKeys&#xa;import com.barrymac.freeplane.addons.llm.services.ResourceLoaderService&#xa;import com.barrymac.freeplane.addons.llm.ui.ImageSelectionDialog&#xa;import com.barrymac.freeplane.addons.llm.ui.ImagePromptEditor&#xa;import com.barrymac.freeplane.addons.llm.prompts.MessageExpander&#xa;import org.freeplane.core.util.LogUtils&#xa;&#xa;import javax.swing.*&#xa;// Removed: import java.util.concurrent.atomic.AtomicBoolean&#xa;import java.util.concurrent.CancellationException&#xa;import java.util.concurrent.ExecutionException&#xa;import java.lang.InterruptedException // Explicit import for clarity&#xa;&#xa;import static com.barrymac.freeplane.addons.llm.ui.UiHelper.showErrorMessage&#xa;import static com.barrymac.freeplane.addons.llm.ui.UiHelper.showInformationMessage&#xa;&#xa;import com.barrymac.freeplane.addons.llm.api.ApiPayloadBuilder&#xa;import com.barrymac.freeplane.addons.llm.api.ImageGeneration&#xa;import com.barrymac.freeplane.addons.llm.api.ApiCallerFactory&#xa;import com.barrymac.freeplane.addons.llm.ResponseParser&#xa;import groovy.json.JsonSlurper&#xa;&#xa;// === Script Entry Point ===&#xa;LogUtils.info(&quot;GenerateImage script started.&quot;)&#xa;&#xa;try {&#xa;    // 1. Load Configuration&#xa;    LogUtils.info(&quot;Loading configuration...&quot;)&#xa;&#xa;    // Images run through the chat provider by default (OpenRouter serves&#xa;    // image-output models on the same endpoint and key), with Novita kept as an&#xa;    // explicit alternative for its cheaper diffusion models.&#xa;    String imageProvider = ConfigKeys.read(config, ConfigKeys.IMAGE_PROVIDER, ImageGeneration.OPENROUTER)&#xa;    String imageModel = ConfigKeys.read(config, ConfigKeys.IMAGE_MODEL,&#xa;            ImageGeneration.DEFAULT_OPENROUTER_IMAGE_MODEL)&#xa;    LogUtils.info(&quot;Image provider: ${imageProvider}, model: ${imageModel}&quot;)&#xa;&#xa;    def novitaApiKey = config.getProperty(&apos;novita.key&apos;, &apos;&apos;)&#xa;&#xa;    // Handle missing key with dialog that persists the value&#xa;    if (imageProvider == ImageGeneration.NOVITA &amp;&amp; !novitaApiKey) {&#xa;        LogUtils.warn(&quot;Novita.ai API key missing - prompting user&quot;)&#xa;&#xa;        // Use main Freeplane frame as parent instead of node&#xa;        // Freeplane&apos;s UITools.showInputDialog now takes a NodeModel rather than&#xa;        // a frame; JOptionPane keeps this stable across Freeplane versions.&#xa;        novitaApiKey = JOptionPane.showInputDialog(&#xa;                ui.currentFrame,&#xa;                &quot;&quot;&quot;&lt;html&gt;Novita.ai API key required for image generation.&lt;br&gt;&#xa;            Get your key at &lt;a href=&apos;https://novita.ai/&apos;&gt;novita.ai&lt;/a&gt;&lt;/html&gt;&quot;&quot;&quot;,&#xa;                &quot;API Key Required&quot;,&#xa;                JOptionPane.QUESTION_MESSAGE // Use constant&#xa;        )&#xa;&#xa;        // Validate input&#xa;        if (!novitaApiKey?.trim()) {&#xa;            LogUtils.info(&quot;User cancelled API key input&quot;)&#xa;            showInformationMessage(ui, &quot;Image generation requires a valid API key&quot;)&#xa;            return // Exit script&#xa;        }&#xa;&#xa;        // Persist the key properly&#xa;        try {&#xa;            config.setProperty(&apos;novita.key&apos;, novitaApiKey.trim())&#xa;            // Freeplane config auto-saves, no need to call save()&#xa;            LogUtils.info(&quot;Novita API key saved to preferences&quot;)&#xa;            // Immediately update local variable with saved value&#xa;            novitaApiKey = config.getProperty(&apos;novita.key&apos;, &apos;&apos;)&#xa;        } catch (Exception e) {&#xa;            LogUtils.severe(&quot;Failed to save API key: ${e.message}&quot;)&#xa;            showErrorMessage(ui, &quot;Failed to save API key: ${e.message}&quot;)&#xa;            return // Exit script&#xa;        }&#xa;    }&#xa;&#xa;    // Then proceed with node selection check&#xa;    LogUtils.info(&quot;Novita API Key verified&quot;)&#xa;    // Create a simple map for now, later use ApiConfig if needed&#xa;    def apiConfig = [novitaApiKey: novitaApiKey]&#xa;&#xa;    // 2. Get Selected Node &amp; Prompt&#xa;    LogUtils.info(&quot;Getting selected node...&quot;)&#xa;    def node = c.selected  // Use the Node proxy directly&#xa;    if (node == null) {&#xa;        showInformationMessage(ui, &quot;Please select a node first to use as the image prompt.&quot;)&#xa;        LogUtils.info(&quot;No node selected.&quot;)&#xa;        return // Exit script&#xa;    }&#xa;    String prompt = node.text?.trim() // Placeholder access&#xa;    if (!prompt) {&#xa;        showInformationMessage(ui, &quot;The selected node has no text to use as an image prompt.&quot;)&#xa;        LogUtils.info(&quot;Selected node has no text.&quot;)&#xa;        return // Exit script&#xa;    }&#xa;    LogUtils.info(&quot;Using prompt from node ${node.id}: &apos;${prompt.take(100)}...&apos;&quot;)&#xa;&#xa;&#xa;    // 3. Generate image prompt using LLM if needed (This part remains synchronous for now)&#xa;    LogUtils.info(&quot;Preparing image prompt...&quot;)&#xa;    String enhancedPrompt = &quot;&quot;&#xa;    def savedTemplate = ConfigManager.getUserProperty(config, &apos;savedImagePromptTemplate&apos;, &apos;&apos;)&#xa;    LogUtils.info(&quot;Loaded savedImagePromptTemplate from config: &apos;${savedTemplate}&apos;&quot;)&#xa;    LogUtils.info(&quot;Saved template check - exists: ${!savedTemplate?.trim().isEmpty()}&quot;) // Use safe navigation and trim check&#xa;&#xa;    if (savedTemplate?.trim().isEmpty()) { // Check if it&apos;s null, empty, or whitespace&#xa;        LogUtils.info(&quot;No valid saved template found - generating enhancement&quot;)&#xa;        def llmProvider = ConfigKeys.read(config, ConfigKeys.PROVIDER, &apos;openrouter&apos;)&#xa;        def llmApiKey = ConfigKeys.read(config, ConfigKeys.API_KEY, &apos;&apos;)?.trim()&#xa;&#xa;        // Image generation is Novita&apos;s job. A chat provider key only buys prompt&#xa;        // enhancement, so a missing one must never block the image.&#xa;        if (!llmApiKey) {&#xa;            LogUtils.info(&apos;No chat provider key configured - using the image prompt as written&apos;)&#xa;            showInformationMessage(ui,&#xa;                    &apos;No chat provider is configured, so the image prompt is used as written. &apos; +&#xa;                    &apos;Add a provider key in the LLM settings when you want prompts enhanced.&apos;)&#xa;            enhancedPrompt = prompt&#xa;        }&#xa;&#xa;        if (llmApiKey) {&#xa;        String systemPrompt&#xa;        try {&#xa;            systemPrompt = ResourceLoaderService.loadTextResource(&apos;/novitaSystemPrompt.txt&apos;)&#xa;            LogUtils.info(&quot;Loaded system prompt template from resources&quot;)&#xa;        } catch (Exception e) {&#xa;            LogUtils.warn(&quot;Could not load system prompt template: ${e.message}&quot;)&#xa;            systemPrompt = &quot;You are an expert image prompt engineer. Enhance this prompt for AI image generation.&quot;&#xa;        }&#xa;&#xa;        // Use the map&apos;s configured chat model rather than a hardcoded legacy id:&#xa;        // prompt enhancement then works with whichever provider the user runs.&#xa;        def promptModel = ConfigManager.loadBaseConfig(config).model&#xa;        def promptRequest = new ApiRequest(&#xa;            model: promptModel,&#xa;            messages: [&#xa;                new Message(role: &apos;system&apos;, content: systemPrompt),&#xa;                new Message(role: &apos;user&apos;, content: prompt)&#xa;            ],&#xa;            temperature: 0.7,&#xa;            maxTokens: 200&#xa;        )&#xa;&#xa;        // Call LLM (Synchronous for now, could be refactored to SwingWorker too if slow)&#xa;        def (apiCaller, progressDialog, llmResponse) = [null, null, null]&#xa;        try {&#xa;            // Using a simple progress dialog here, not the cancellable one yet&#xa;            progressDialog = ImageSelectionDialog.createProgressDialog(ui, &quot;Generating Prompt&quot;, &quot;Creating image description...&quot;)&#xa;            progressDialog.visible = true&#xa;            apiCaller = ApiCallerFactory.createApiCaller([ui: ui]).make_api_call&#xa;            llmResponse = apiCaller(llmProvider, llmApiKey, promptRequest)&#xa;        } catch (Exception e) {&#xa;            showErrorMessage(ui, &quot;Prompt generation failed: ${e.message.split(&apos;\n&apos;).head()}&quot;)&#xa;            return // Exit script&#xa;        } finally {&#xa;            progressDialog?.dispose()&#xa;        }&#xa;&#xa;        try {&#xa;            def json = new JsonSlurper().parseText(llmResponse)&#xa;            enhancedPrompt = json.choices[0].message.content.trim()&#xa;            LogUtils.info(&quot;LLM generated prompt: ${enhancedPrompt.take(100)}...&quot;)&#xa;        } catch (Exception e) {&#xa;            LogUtils.warn(&quot;Failed to parse LLM response, using original prompt: ${e.message}&quot;)&#xa;            enhancedPrompt = prompt // Fallback&#xa;        }&#xa;        }&#xa;    } else {&#xa;        LogUtils.info(&quot;Using saved template from config, skipping LLM enhancement.&quot;) // Adjusted log&#xa;    }&#xa;&#xa;    // --- MODIFY PARAMETER PREPARATION ---&#xa;    // Prepare initial state for editor - Load parameters from config or use defaults via ConfigManager&#xa;    def initialParams = [&#xa;        steps   : ConfigManager.getUserProperty(config, &apos;imagegenSteps&apos;, &apos;4&apos;).toInteger(), // Use new key&#xa;        width   : ConfigManager.getUserProperty(config, &apos;imagegenWidth&apos;, &apos;256&apos;).toInteger(), // Use new key&#xa;        height  : ConfigManager.getUserProperty(config, &apos;imagegenHeight&apos;, &apos;256&apos;).toInteger(), // Use new key&#xa;        imageNum: ConfigManager.getUserProperty(config, &apos;imagegenImageNum&apos;, &apos;4&apos;).toInteger(), // Use new key&#xa;        seed    : new Random().nextInt(Integer.MAX_VALUE) // Seed is always random&#xa;    ]&#xa;    LogUtils.info(&quot;Prepared initial parameters for editor via ConfigManager: ${initialParams}&quot;)&#xa;    // --- END MODIFY PARAMETER PREPARATION ---&#xa;&#xa;    String userPromptTemplate = ResourceLoaderService.loadTextResource(&apos;/imageUserPrompt.txt&apos;)&#xa;    boolean useSaved = savedTemplate &amp;&amp; !savedTemplate.trim().isEmpty() // More explicit check&#xa;    LogUtils.info(&quot;Use saved template? ${useSaved}&quot;)&#xa;    def initialTemplate = useSaved ? savedTemplate : &quot;${userPromptTemplate}\n\n${enhancedPrompt}&quot;.trim()&#xa;    LogUtils.info(&quot;Initial template for editor: &apos;${initialTemplate}&apos;&quot;)&#xa;    def binding = MessageExpander.createBinding(node, null, null, null, null) + [generatedPrompt: enhancedPrompt]&#xa;&#xa;    // 4. Show Prompt Editor and Handle Result (Uses the map result now)&#xa;    LogUtils.info(&quot;Showing Image Prompt Editor...&quot;)&#xa;    // Pass initialParams, although editor now loads its own state from config&#xa;    Map editorResult = ImagePromptEditor.showPromptEditor(ui, initialTemplate, initialParams, config)&#xa;&#xa;    // Handle actions based on editorResult&#xa;    switch (editorResult.action) {&#xa;        case &apos;Generate&apos;:&#xa;            LogUtils.info(&quot;User chose &apos;Generate&apos;.&quot;)&#xa;            // The editor lets the user change service and model; honour that for&#xa;            // this run as well as saving it for the next.&#xa;            imageProvider = editorResult.params?.provider ?: imageProvider&#xa;            imageModel = editorResult.params?.model ?: imageModel&#xa;            String finalUserTemplate = editorResult.prompt&#xa;            Map generationParams = editorResult.params // Contains validated params from editor&#xa;&#xa;            // Expand the final template provided by the user&#xa;            LogUtils.info(&quot;Expanding final user template...&quot;)&#xa;            String finalPrompt = MessageExpander.expandTemplate(finalUserTemplate, binding)&#xa;            LogUtils.info(&quot;Expanded final prompt: ${finalPrompt.take(100)}...&quot;)&#xa;&#xa;&#xa;            // 5. Build the payload the chosen provider expects&#xa;            LogUtils.info(&quot;Building ${imageProvider} payload...&quot;)&#xa;            def payloadMap = imageProvider == ImageGeneration.NOVITA ?&#xa;                    ApiPayloadBuilder.buildNovitaImagePayload(&#xa;                            finalPrompt,&#xa;                            generationParams.steps,&#xa;                            generationParams.width,&#xa;                            generationParams.height,&#xa;                            generationParams.imageNum,&#xa;                            generationParams.seed) :&#xa;                    ImageGeneration.openRouterPayload(imageModel, finalPrompt, generationParams.imageNum)&#xa;            LogUtils.info(&quot;Built ${imageProvider} payload: ${payloadMap}&quot;)&#xa;&#xa;            // 6. Create API Caller Closure&#xa;            LogUtils.info(&quot;Creating Novita API caller closure...&quot;)&#xa;            def imageKey = ImageGeneration.keyFor(imageProvider, config)&#xa;            if (!imageKey) {&#xa;                showErrorMessage(ui,&#xa;                        &quot;No API key is configured for ${imageProvider}. Add one in the LLM settings &quot; +&#xa;                                &quot;to generate images.&quot;)&#xa;                return&#xa;            }&#xa;            Closure callNovitaApi = ApiCallerFactory.createApiCaller([ui: ui])&#xa;                    .make_api_call.curry(imageProvider, imageKey)&#xa;&#xa;            // --- SwingWorker Implementation ---&#xa;            LogUtils.info(&quot;Setting up SwingWorker for Novita API call...&quot;)&#xa;            SwingWorker&lt;String, Void&gt; worker = null // Declare worker variable here&#xa;            JDialog progressDialog = null // Declare progressDialog variable here&#xa;&#xa;            // Define the cancellation action&#xa;            def cancelAction = {&#xa;                LogUtils.info(&quot;User requested cancellation.&quot;)&#xa;                if (worker != null &amp;&amp; !worker.isDone()) {&#xa;                    LogUtils.info(&quot;Attempting to cancel SwingWorker (interrupting thread)...&quot;)&#xa;                    worker.cancel(true) // Pass true to attempt interruption&#xa;                } else {&#xa;                    LogUtils.info(&quot;Cancellation requested but worker is null or already done.&quot;)&#xa;                }&#xa;            }&#xa;&#xa;            // Create the cancellable progress dialog&#xa;            progressDialog = ImageSelectionDialog.createProgressDialog(&#xa;                    ui,&#xa;                    &quot;Generating Image&quot;,&#xa;                    &quot;Creating images with Novita.ai...&quot;,&#xa;                    cancelAction&#xa;            )&#xa;&#xa;            // Define the SwingWorker&#xa;            worker = new SwingWorker&lt;String, Void&gt;() {&#xa;                @Override&#xa;                protected String doInBackground() throws Exception {&#xa;                    LogUtils.info(&quot;SwingWorker: doInBackground executing on thread: &quot; + Thread.currentThread().getName())&#xa;&#xa;                    // Check only for interruption *before* the call&#xa;                    if (Thread.currentThread().isInterrupted()) {&#xa;                        LogUtils.warn(&quot;SwingWorker: Thread interrupted BEFORE API call.&quot;) // More specific log&#xa;                        throw new InterruptedException(&quot;Operation cancelled by user before API call.&quot;)&#xa;                    }&#xa;&#xa;                    LogUtils.info(&quot;SwingWorker: Calling Novita API...&quot;) // Log right before the call&#xa;                    String rawApiResponse&#xa;                    try {&#xa;                        LogUtils.info(&quot;SwingWorker: Entering try block for callNovitaApi...&quot;)&#xa;                        rawApiResponse = callNovitaApi(payloadMap) // Execute the blocking call&#xa;                        LogUtils.info(&quot;SwingWorker: callNovitaApi returned successfully.&quot;)&#xa;                    } catch (InterruptedException e) {&#xa;                        // If callNovitaApi itself throws InterruptedException&#xa;                        LogUtils.warn(&quot;SwingWorker: API call was interrupted (InterruptedException caught).&quot;, e)&#xa;                        Thread.currentThread().interrupt() // Re-interrupt the thread&#xa;                        throw e // Re-throw InterruptedException&#xa;                    } catch (Exception e) {&#xa;                        // Catch other exceptions during the call&#xa;                        LogUtils.severe(&quot;SwingWorker: Exception during API call: ${e.message}&quot;, e)&#xa;                        throw e // Re-throw other exceptions&#xa;                    }&#xa;&#xa;                    // Check for interruption *after* the call returns successfully&#xa;                    if (Thread.currentThread().isInterrupted()) {&#xa;                        LogUtils.warn(&quot;SwingWorker: Thread interrupted AFTER API call.&quot;) // More specific log&#xa;                        throw new InterruptedException(&quot;Operation cancelled by user after API call.&quot;)&#xa;                    }&#xa;&#xa;                    LogUtils.info(&quot;SwingWorker: doInBackground finished successfully.&quot;) // Changed log message&#xa;                    return rawApiResponse&#xa;                }&#xa;&#xa;                @Override&#xa;                protected void done() {&#xa;                    LogUtils.info(&quot;SwingWorker: done() method started.&quot;)&#xa;                    // Dispose the initial progress dialog *before* potentially showing another modal dialog&#xa;                    if (progressDialog != null) {&#xa;                        LogUtils.info(&quot;SwingWorker: Disposing initial progress dialog.&quot;)&#xa;                        progressDialog.dispose()&#xa;                    }&#xa;&#xa;                    try {&#xa;                        // Check worker&apos;s cancelled status first&#xa;                        if (isCancelled()) {&#xa;                            LogUtils.warn(&quot;SwingWorker: Task was cancelled by user (isCancelled() is true).&quot;)&#xa;                            return // Stop processing&#xa;                        }&#xa;&#xa;                        // Call get() to retrieve result or propagate exceptions&#xa;                        String rawApiResponse = get() // Throws CancellationException if cancelled, ExecutionException if error in doInBackground&#xa;&#xa;                        // If get() succeeded:&#xa;                        LogUtils.info(&quot;SwingWorker: API call successful. Parsing response...&quot;)&#xa;                        List&lt;String&gt; imageUrls = ResponseParser.parseImageResponse(rawApiResponse, imageProvider)&#xa;                        if (imageUrls.isEmpty()) {&#xa;                            LogUtils.error(&quot;SwingWorker: API response did not contain any image URLs.&quot;)&#xa;                            showErrorMessage(ui, &quot;The API did not return any image URLs. Check logs.&quot;)&#xa;                            return&#xa;                        }&#xa;                        LogUtils.info(&quot;SwingWorker: Parsed image URLs: ${imageUrls.size()} found.&quot;)&#xa;&#xa;                        // --- NEW LOGIC: If only one image, attach directly, else show selection dialog ---&#xa;                        if (generationParams.imageNum == 1 &amp;&amp; imageUrls.size() == 1) {&#xa;                            LogUtils.info(&quot;Only one image requested/generated; attaching directly to node.&quot;)&#xa;                            // Download and attach the image directly&#xa;                            try {&#xa;                                // Download image bytes&#xa;                                def url = imageUrls[0]&#xa;                                byte[] imageBytes&#xa;                                if (url.startsWith(&quot;/&quot;)) {&#xa;                                    imageBytes = com.barrymac.freeplane.addons.llm.services.ResourceLoaderService.loadBundledResourceBytes(url)&#xa;                                } else {&#xa;                                    def connection = new URL(url).openConnection()&#xa;                                    connection.connectTimeout = 10000&#xa;                                    connection.readTimeout = 30000&#xa;                                    imageBytes = connection.inputStream.bytes&#xa;                                }&#xa;                                if (imageBytes) {&#xa;                                    String baseName = com.barrymac.freeplane.addons.llm.services.ImageAttachmentHandler.sanitizeBaseName(node.text)&#xa;                                    String extension = com.barrymac.freeplane.addons.llm.services.ImageAttachmentHandler.getFileExtension(url)&#xa;                                    com.barrymac.freeplane.addons.llm.services.ImageAttachmentHandler.attachImageToNode(node, imageBytes, baseName, extension)&#xa;                                    LogUtils.info(&quot;Image attached directly to node (single image flow).&quot;)&#xa;                                } else {&#xa;                                    showErrorMessage(ui, &quot;Failed to download the generated image.&quot;)&#xa;                                }&#xa;                            } catch (Exception e) {&#xa;                                LogUtils.severe(&quot;Error attaching single generated image: ${e.message}&quot;, e)&#xa;                                showErrorMessage(ui, &quot;Failed to attach generated image: ${e.message?.split(&apos;\n&apos;)?.head()}&quot;)&#xa;                            }&#xa;                        } else {&#xa;                            // Multiple images: show selection dialog as before&#xa;                            LogUtils.info(&quot;Multiple images generated; showing selection dialog.&quot;)&#xa;                            ImageSelectionDialog.handleImageSelection(ui, imageUrls, node, config)&#xa;                        }&#xa;&#xa;                    } catch (CancellationException e) {&#xa;                        // Explicitly caught if worker was cancelled *before* get() was called or if get() throws it&#xa;                        LogUtils.warn(&quot;SwingWorker: Operation cancelled (CancellationException caught).&quot;, e)&#xa;                    } catch (ExecutionException e) {&#xa;                        Throwable cause = e.getCause() ?: e&#xa;                        // Check if the cause was an InterruptedException from doInBackground&#xa;                        if (cause instanceof InterruptedException) {&#xa;                            LogUtils.warn(&quot;SwingWorker: Operation interrupted during execution (InterruptedException cause).&quot;, cause)&#xa;                            Thread.currentThread().interrupt() // Preserve interrupt status&#xa;                        } else {&#xa;                            // Handle other execution errors&#xa;                            LogUtils.severe(&quot;SwingWorker: Error during API call execution: ${cause.message}&quot;, cause)&#xa;                            showErrorMessage(ui, &quot;Image Generation Error: ${cause.message?.split(&apos;\n&apos;)?.head()}&quot;)&#xa;                        }&#xa;                    } catch (InterruptedException e) {&#xa;                        // If the done() thread itself is interrupted&#xa;                        LogUtils.warn(&quot;SwingWorker: done() method interrupted.&quot;, e)&#xa;                        Thread.currentThread().interrupt() // Preserve interrupt status&#xa;                    } catch (Exception e) {&#xa;                        LogUtils.severe(&quot;SwingWorker: Unexpected error in done() method: ${e.message}&quot;, e)&#xa;                        showErrorMessage(ui, &quot;An unexpected error occurred: ${e.message?.split(&apos;\n&apos;)?.head()}&quot;)&#xa;                    }&#xa;                    LogUtils.info(&quot;SwingWorker: done() method finished.&quot;)&#xa;                }&#xa;            } // End SwingWorker definition&#xa;&#xa;            // Start the worker FIRST&#xa;            worker.execute()&#xa;            LogUtils.info(&quot;SwingWorker started.&quot;)&#xa;            // THEN show the modal progress dialog&#xa;            progressDialog.visible = true&#xa;            LogUtils.info(&quot;Progress dialog is now visible.&quot;)&#xa;&#xa;            break // End of &apos;Generate&apos; case&#xa;&#xa;        case &apos;Cancel&apos;:&#xa;            LogUtils.info(&quot;User cancelled the Image Prompt Editor.&quot;)&#xa;            return // Stop script&#xa;            break // Keep break for consistency&#xa;&#xa;        case &apos;Error&apos;:&#xa;            LogUtils.error(&quot;Image Prompt Editor returned an error: ${editorResult.message}&quot;)&#xa;            showErrorMessage(ui, &quot;Could not open image editor: ${editorResult.message}&quot;)&#xa;            return // Stop script&#xa;            break // Keep break for consistency&#xa;&#xa;        default:&#xa;            LogUtils.warn(&quot;Unknown action received from ImagePromptEditor: ${editorResult.action}&quot;)&#xa;            return // Stop script&#xa;            break // Keep break for consistency&#xa;    }&#xa;&#xa;} catch (Exception e) { // Catch errors during setup before worker starts&#xa;    LogUtils.severe(&quot;An unexpected error occurred in GenerateImage script setup: ${e.message}&quot;, e)&#xa;    showErrorMessage(ui, &quot;An unexpected setup error occurred: ${e.message.split(&apos;\n&apos;).head()}&quot;)&#xa;} finally {&#xa;    LogUtils.info(&quot;GenerateImage script main execution path finished (SwingWorker may still be running).&quot;)&#xa;}&#xa;" ID="ID_1967302885" CREATED="1794972873865" MODIFIED="1794972873866"/>
</node>
